import unittest
class TestSandwich(unittest.TestCase):
    def test_run(self):
        ingredients = ["Bread", "Ham", "Cheese", "Lettuce", "Bread"]
        try:
            bread1, *fillings, bread2 = ingredients
            self.assertEqual(bread1, "Bread", "bread1 should be 'Bread'")
            self.assertEqual(bread2, "Bread", "bread2 should be 'Bread'")
            self.assertEqual(fillings, ["Ham", "Cheese", "Lettuce"], "fillings should be the middle list")
        except Exception as e:
            self.fail(f"Error: {e}")
if __name__ == '__main__': unittest.main()

