import unittest
class Box:
    def __init__(self):
        self.__secret = "Gold"
    def reveal(self):
        return self.__secret
class TestBox(unittest.TestCase):
    def test_access(self):
        b = Box()
        # Verify direct access fails
        try:
            _ = b.__secret
            self.fail("Direct access to __secret should fail! / ¡El acceso directo a __secret debería fallar!")
        except AttributeError:
            pass # This is expected

        # Verify method access works
        self.assertEqual(b.reveal(), "Gold", "The reveal method should work / El método reveal debería funcionar")
if __name__ == '__main__': unittest.main()
